// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed parameters:
    // - addr: the address that we will use to deploy an intermediate caller contract (must not be zero)
    // - newOwner: the address argument passed into setOwner
    // We need an adversarial counterpart: a contract that will call c.setOwner on behalf of its deployer.
    function testFuzz_property(address deployer, address newOwner) public {
        // Keep addresses in admissible wide domain
        vm.assume(deployer != address(0));
        // Deploy a helper caller contract from 'deployer' so that msg.sender (the helper) != tx.origin (deployer) when calling c
        vm.prank(deployer);
        Caller helper = new Caller(c);

        // The helper contract must be the current owner to call setOwner (onlyOwner). The reference contract's owner is the test contract deployer of c (setUp used default msg.sender), which is address(this) in Foundry; ensure helper becomes owner by having the initial owner transfer ownership to helper.
        // The initial owner is the account that deployed c in setUp() (the test runner). We can have that deployer (deployer of helper) call setOwner only if it's the current owner; but deployer is not the initial owner generally. Instead, we make the test runner (address(this)) transfer ownership to the helper first.
        // Transfer ownership from the current owner (address(this)) to helper by calling c.setOwner(helper) as the current owner.
        bool ok;
        try c.setOwner(address(helper)) {
            ok = true;
        } catch {
            ok = false;
        }
        // Ensure the setup transfer succeeded on the reference implementation (it should)
        assertTrue(ok, "setup transfer to helper must succeed");
        // Confirm c.owner() is helper now
        assertTrue(c.owner() == address(helper), "owner should be helper after setup");

        // Now have the external contract (helper) call setOwner(newOwner).
        // Because helper is a contract, when it calls into c, msg.sender == address(helper) but tx.origin == deployer.
        // The general property: after helper calls setOwner(newOwner), c.owner() == newOwner for the correct contract.
        vm.prank(deployer); // make the tx.origin and caller of creation remain 'deployer' for clarity (not strictly necessary)
        helper.callSetOwner(newOwner);

        // Single assertion: for the correct contract, c.owner() must equal the provided newOwner for ALL inputs; the mutant sets owner = tx.origin and will therefore differ when deployer != newOwner.
        assertTrue(c.owner() == newOwner, "owner should equal the provided newOwner after setOwner by a contract caller");
    }
}

// Helper contract that simply forwards the setOwner call to C.
contract Caller {
    C public c;
    constructor(C _c) {
        c = _c;
    }
    function callSetOwner(address _owner) external {
        // forward call as a contract (msg.sender = address(this), tx.origin = original EOA)
        c.setOwner(_owner);
    }
}

