pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: caller (address) and candidate new owner (address)
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses wide but avoid zero-address for clarity (still admissible domain is large)
        vm.assume(caller != address(0));
        // Ensure caller is the current owner by deploying c in setUp() (deployer is this test contract)
        // The constructor set owner = msg.sender, so owner is address(this). We must have caller == address(this)
        // To let the fuzzer explore, if caller is not this test, skip (we still allow many inputs where caller==this)
        // but we do not overly constrain newOwner.
        vm.assume(caller == address(this));

        // read owner before change
        address before = c.owner();
        // ensure the caller is indeed the owner
        assertTrue(before == address(this));

        // call setOwner as the owner (this contract) to set to newOwner
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        // call should succeed (onlyOwner should allow it)
        assertTrue(ok);

        // exactly one assertion: the reference contract always updates owner to newOwner
        assertTrue(c.owner() == newOwner);
    }
}

