pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: caller (as address) and newOwner candidate
    function testFuzz_property(address caller, address newOwner) public {
        // Domain restrictions: the caller must be non-zero and the newOwner can be any address
        vm.assume(caller != address(0));

        // Ensure the caller is the current owner by impersonating deployer (setUp deployed c from this test contract)
        // In setUp, c was created by this contract, so address(this) is the owner.
        // We need to transfer ownership to `caller` first so that caller is the owner who can call setOwner.
        // Only the current owner (this) can call setOwner to set owner to caller.

        // First, as the current owner (this contract), set owner to `caller`.
        bool ok;
        try c.setOwner(caller) { ok = true; } catch { ok = false; }
        // This must succeed on the reference implementation for any non-zero caller.
        // If this call failed, the rest of the test is not meaningful.
        vm.assume(ok);

        // Now caller should be the owner. Impersonate caller and call setOwner(newOwner).
        vm.prank(caller);
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        // On the reference, ok must be true (caller was owner), and owner() must equal newOwner.
        // We assert the universal property: after a legitimate owner calls setOwner(newOwner), c.owner() == newOwner.
        // This will hold for the reference for all admissible inputs; the mutant that omits the assignment will violate it for some fuzzed newOwner.
        assertTrue(c.owner() == newOwner);
    }
}

