pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: the newOwner candidate and the actor who will attempt the change
    function testFuzz_property(address newOwner, address actor) public {
        // keep addresses in the normal EOA range (not zero) but otherwise wide
        vm.assume(actor != address(0));
        vm.assume(newOwner != address(0));

        // fund the actor so prank works even if sending value (not needed here but safe)
        vm.deal(actor, 1 ether);

        // The contract's deployer (this test) is the initial owner (setUp used new C()),
        // but we need the actor to be owner to exercise setOwner under onlyOwner.
        // Arrange: have the current owner (this test contract) transfer ownership to actor
        // by calling setOwner(actor) as the owner.
        bool ok;
        // call as this contract (owner) to set actor as owner
        try c.setOwner(actor) {
            ok = true;
        } catch {
            ok = false;
        }
        // must succeed on reference; require to proceed with the scenario
        assertTrue(ok);

        // Now actor (the new owner) calls setOwner with the fuzzed newOwner value
        vm.prank(actor);
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General property (single assertion): after an owner-call to setOwner(newOwner),
        // the contract's public owner() equals the provided newOwner.
        // This holds for the reference implementation for all inputs; the mutant that
        // assigns owner = msg.sender will violate this for some inputs (whenever newOwner != actor).
        assertTrue(c.owner() == newOwner);
    }
}

