import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameter: the candidate new owner address
    function testFuzz_property(address newOwner) public {
        // keep the domain wide but avoid the zero address as an uninteresting trivial case
        // (the property should still hold for zero, but excluding it keeps the fuzzer exploring other addresses)
        // Note: we do NOT exclude the zero address strictly to allow failing mutant to be found via fuzzer; use assume to only avoid blocking other tooling
        // vm.assume(newOwner != address(0)); // optional; commented out to keep wide

        // Caller must be the current owner to call setOwner per onlyOwner modifier
        address caller = address(this);
        // c was deployed in setUp(), its owner is set to the deployer (this test contract). We call directly.

        // Call setOwner as the owner
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract guarantees that after setOwner(newOwner) completes successfully,
        // c.owner() equals the supplied newOwner. We assert that when the call did not revert, the stored owner equals newOwner.
        // This single assertion is satisfied by the reference for all inputs and broken by the mutant for some inputs.
        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            // If the call reverted, the invariant about successful completion doesn't apply; still assert that revert happened only
            // This keeps the test logic well-defined for all inputs. The reference contract's setOwner will not revert when called by the owner,
            // so for the reference contract ok will always be true and the main assertion checked. The mutant may still allow the call to succeed
            // but record address(0) and thus fail the assertion above for some fuzzed newOwner.
            assertTrue(!ok);
        }
    }
}

