pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameters: caller and newOwner
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses wide but avoid zero-address ambiguity
        vm.assume(caller != address(0));

        // ensure caller has some ETH so it can be a regular externally-owned caller if needed
        vm.deal(caller, 1 ether);

        // Capture precondition: initial owner is the contract deployer (this test)
        address initialOwner = c.owner();

        // The general rule: only the current owner can successfully call setOwner and change owner to newOwner.
        // We simulate the call as 'caller'. If caller == initialOwner, the call should succeed and set owner to newOwner.
        // If caller != initialOwner, the call should revert and owner should remain unchanged.

        bool ok;
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        // Single assertion reading c: the reference contract always ensures that
        // (ok == true) iff (caller == initialOwner), and when ok==true the owner equals newOwner.
        // We assert the core observable consequence: if the call reported success then c.owner()==newOwner,
        // otherwise c.owner()==initialOwner. This holds for the reference and is violated by the mutant for some inputs.
        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            assertTrue(c.owner() == initialOwner);
        }
    }
}

