pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed params: caller (who calls setOwner) and newOwner (the address passed to setOwner).
    // General rule: only the current owner may successfully call setOwner; after a successful call,
    // c.owner() equals the provided newOwner. The mutant reverses the ownership check.
    function testFuzz_property(address caller, address newOwner) public {
        // Keep domain wide but avoid zero-address for clearer semantics (still wide).
        // The correctness property should hold for all addresses including zero, but to avoid
        // degenerate cases with payable/address issues we only exclude address(0) here.
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // Arrange: record the pre-call owner
        address preOwner = c.owner();

        // Act: have `caller` invoke setOwner(newOwner), capturing success/failure
        bool ok;
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        // Assert: in the correct contract, the call succeeds if and only if caller == preOwner,
        // and when it succeeds, owner() == newOwner; when it fails, owner() == preOwner.
        // Combine those facts into one boolean that must always be true for the reference.
        address postOwner = c.owner();

        bool expectedSucceeded = (caller == preOwner);
        bool observedSucceeded = ok;
        bool ownerUpdatedCorrectly = observedSucceeded ? (postOwner == newOwner) : (postOwner == preOwner);

        // Single assertion stating the universal property the reference must satisfy for all inputs.
        assertTrue((observedSucceeded == expectedSucceeded) && ownerUpdatedCorrectly);
    }
}

